BEGIN;
ALTER TABLE public.sylaj_complete_records ADD COLUMN IF NOT EXISTS plan_revision bigint NOT NULL DEFAULT 1;
CREATE OR REPLACE FUNCTION public.sylaj_plan_revision() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF NEW.module='plan' AND (NEW.payload IS DISTINCT FROM OLD.payload OR NEW.team_id IS DISTINCT FROM OLD.team_id) THEN NEW.plan_revision=OLD.plan_revision+1; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS sylaj_plan_revision ON public.sylaj_complete_records;
CREATE TRIGGER sylaj_plan_revision BEFORE UPDATE ON public.sylaj_complete_records FOR EACH ROW EXECUTE FUNCTION public.sylaj_plan_revision();
CREATE TABLE IF NOT EXISTS public.sylaj_plan_reads(plan_id bigint REFERENCES public.sylaj_complete_records(id), revision bigint NOT NULL, reader uuid NOT NULL, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(plan_id,revision,reader));
CREATE TABLE IF NOT EXISTS public.sylaj_push_subscriptions(user_id uuid NOT NULL, endpoint text NOT NULL, subscription jsonb NOT NULL, PRIMARY KEY(user_id,endpoint));
ALTER TABLE public.sylaj_plan_reads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sylaj_push_subscriptions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sylaj_plan_reads,public.sylaj_push_subscriptions FROM anon,authenticated;
GRANT SELECT ON public.sylaj_plan_reads TO authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sylaj_push_subscriptions TO authenticated;
DROP POLICY IF EXISTS plan_reads_select ON public.sylaj_plan_reads;
CREATE POLICY plan_reads_select ON public.sylaj_plan_reads FOR SELECT TO authenticated USING(public.sylaj_complete_admin() OR reader=auth.uid());
DROP POLICY IF EXISTS push_own ON public.sylaj_push_subscriptions;
CREATE POLICY push_own ON public.sylaj_push_subscriptions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.sylaj_ack_plan(p_id bigint,p_revision bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.sylaj_complete_records r JOIN public.ekipe e ON e.id::text=r.team_id WHERE r.id=p_id AND r.plan_revision=p_revision AND r.module='plan' AND r.deleted_at IS NULL AND e.vodja_id=auth.uid()) THEN RAISE EXCEPTION 'Plan unavailable'; END IF; INSERT INTO public.sylaj_plan_reads(plan_id,revision,reader) VALUES(p_id,p_revision,auth.uid()) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.sylaj_ack_plan(bigint,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.sylaj_ack_plan(bigint,bigint) TO authenticated;
COMMIT;
